const rawInput = typeof item === 'object' && item.json ? item.json.chatInput : $json.chatInput;

if (!rawInput) {
    throw new Error("No input received from the chat trigger.");
}

const urlRegex = /(https?:\/\/[^\s]+)/g;
const match = rawInput.match(urlRegex);

if (!match) {
    throw new Error("No valid URL detected.");
}

let cleanUrl = match[0];

try {
    const urlObj = new URL(cleanUrl);
    urlObj.search = "";
    cleanUrl = urlObj.toString();

    if (cleanUrl.endsWith('/')) {
        cleanUrl = cleanUrl.slice(0, -1);
    }
} catch (e) {
    cleanUrl = cleanUrl.split('?')[0];
    if (cleanUrl.endsWith('/')) {
        cleanUrl = cleanUrl.slice(0, -1);
    }
}

return [{ json: { url: cleanUrl } }];

