// This loops through every item currently in the n8n execution batch automatically
return $input.all().map((item, index) => {
  const llmOutput = item.json.output;

  // Safely grab the original URL from the upstream JavaScript parsing node for this specific item index
  const originalUrl = $('Code in JavaScript').first(index).json.url;

  let processedTemplate = llmOutput.template;

  // Feature [X] Newline after each dot "."
  processedTemplate = processedTemplate.replace(/\.\s+/g, ".\n");

  // Feature [X] Reformat [[ ]] into sleek inline markdown code blocks `placeholder`
  processedTemplate = processedTemplate.replace(/\[\[\s*(.*?)\s*\]\]/g, "`$1` ` `");

  // Extract the very first sentence to use as the clean Notion Page Title
  const firstSentenceMatch = processedTemplate.match(/^([^.\n]+)/);
  const pageTitle = firstSentenceMatch ? firstSentenceMatch[1].trim() : "New Script Template";

  return {
    json: {
      title: pageTitle,
      url: originalUrl,
      template: processedTemplate,
      stage: llmOutput.stage,
      cta: llmOutput.cta,
      type: llmOutput.type,
      perspective: llmOutput.perspective
    }
  };
});
